import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.Bs_1Tt6f.js";const u=JSON.parse('{"title":"Custom Manuscripts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/custom-manuscripts.md","filePath":"docs/custom-manuscripts.md"}'),s={name:"docs/custom-manuscripts.md"};function r(i,e,p,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="custom-manuscripts" tabindex="-1">Custom Manuscripts <a class="header-anchor" href="#custom-manuscripts" aria-label="Permalink to &quot;Custom Manuscripts&quot;">​</a></h1><p><strong>Custom Manuscripts</strong> is the lightweight path for documenting a notation <strong>without IIIF, folios, line regions or polygons</strong>: you paste or upload snippet images directly.</p><ul><li>A <strong>collection</strong> is a named source with its own list of patterns (declared by code) and its images.</li><li>Add snippets by pasting or uploading images, give each a pattern, an optional Ref ID, variant and caption.</li><li>Collections can be <strong>published</strong>, which makes them appear in the public documentation like annotated manuscripts.</li></ul><p>Snippet images can be large, so they are kept in a separate file in your workspace folder (<code>direct-snippets.json</code>) and in the browser&#39;s database, and are included in backups.</p><h2 id="proofreading-pdf-and-json-for-one-manuscript" tabindex="-1">Proofreading: PDF and JSON for one manuscript <a class="header-anchor" href="#proofreading-pdf-and-json-for-one-manuscript" aria-label="Permalink to &quot;Proofreading: PDF and JSON for one manuscript&quot;">​</a></h2><p>Each custom manuscript can be handed to someone else to check. Open the manuscript in <strong>Custom Manuscripts</strong> and use the <strong>Proofreading</strong> block (below the title and notes):</p><table tabindex="0"><thead><tr><th>Button</th><th>What it gives you</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Save as PDF</strong></td><td>A printable copy: title and notes, then every declared pattern with its notation drawn from the code, the code, the label, and each snippet image with its Ref ID, caption and a tick box. Snippets without a pattern follow under <em>Unassigned</em>.</td><td>Printing, ticking snippets that are filed correctly, writing corrections by hand.</td></tr><tr><td><strong>Save as JSON file</strong></td><td>One file holding only this manuscript, <strong>images included</strong>.</td><td>Sending the manuscript to a colleague who corrects it in the app.</td></tr></tbody></table><h3 id="round-trip-with-a-proofreader" tabindex="-1">Round trip with a proofreader <a class="header-anchor" href="#round-trip-with-a-proofreader" aria-label="Permalink to &quot;Round trip with a proofreader&quot;">​</a></h3><ol><li><strong>You</strong> save the JSON file (and the PDF, if the proofreader prefers paper) and send it.</li><li><strong>The proofreader</strong> opens <strong>Settings → Import</strong> and drops the file there (several files can be dropped at once). The manuscript appears under <strong>Custom Manuscripts</strong>, where captions, Ref IDs, patterns and the pattern of each snippet can be corrected.</li><li><strong>The proofreader</strong> opens the manuscript and saves it again with <strong>Save as JSON file</strong>, then sends that file back.</li><li><strong>You</strong> import the returned file the same way. Because the manuscript already exists, the import list marks it as a conflict and shows the number of images and patterns on both sides; choose: <ul><li><strong>Skip (keep mine)</strong>: keep your version.</li><li><strong>Import as copy</strong>: keep both; the returned one gets the siglum &quot;… (copy)&quot; and is not published, so the two can be compared.</li><li><strong>Overwrite mine</strong>: replace your version with the returned one.</li></ul></li></ol><p>A manuscript counts as the same one when it has the same internal id <strong>or</strong> the same siglum (upper and lower case and surrounding spaces are ignored).</p><h3 id="do-manuscripts-have-to-be-proofread-before-they-are-published" tabindex="-1">Do manuscripts have to be proofread before they are published? <a class="header-anchor" href="#do-manuscripts-have-to-be-proofread-before-they-are-published" aria-label="Permalink to &quot;Do manuscripts have to be proofread before they are published?&quot;">​</a></h3><p>The app does not require it: <strong>Publish</strong> is a separate switch and does not depend on any proofreading step. Whether an unchecked manuscript may be uploaded to the corpus is a decision for the editors of the corpus, not something the app enforces. A manuscript that is still being checked can be left unpublished, and published after the corrected file has been imported.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><ul><li>The PDF needs at least one snippet; a manuscript without images has nothing to print.</li><li>The JSON file carries the manuscript&#39;s own data only. Source metadata (the fields under Settings) and app settings stay in each person&#39;s workspace.</li><li>The full backup (<strong>Settings → Export → Everything</strong>) still includes every custom manuscript; <strong>Settings → Export</strong> can also save several custom manuscripts at once, in one file or as a ZIP with one file each.</li></ul>',14)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
